import{_ as o,o as d,c as t,ag as c}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"内网 LLM 端点模型盘点与可用性实测（2026-10-23）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-brain/model-endpoint-inventory-2026-10-23.md","filePath":"topics/ai-brain/model-endpoint-inventory-2026-10-23.md"}'),r={name:"topics/ai-brain/model-endpoint-inventory-2026-10-23.md"};function n(a,e,s,i,l,p){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="内网-llm-端点模型盘点与可用性实测-2026-10-23" tabindex="-1">内网 LLM 端点模型盘点与可用性实测（2026-10-23） <a class="header-anchor" href="#内网-llm-端点模型盘点与可用性实测-2026-10-23" aria-label="Permalink to &quot;内网 LLM 端点模型盘点与可用性实测（2026-10-23）&quot;">​</a></h1><blockquote><p>端点：<code>http://10.111.32.151:3001/v1</code>（new-api 网关） 背景：<code>123-copy</code> 的默认模型 <code>deepseek-v4-flash-0731</code> 实测 <strong>503</strong> → 已从 <code>config.yaml</code> 删除，默认改指 <code>deepseek-v4.1-flash</code> 方法：<code>GET /v1/models</code> 拉端点自报清单 → <strong>逐个发真实 chat completion</strong>（<code>max_tokens: 32</code>，8 并发，python <code>ProxyHandler({})</code> 禁本地代理）</p></blockquote><h2 id="一、结论-端点自报-20-个-实际可用-6-个" tabindex="-1">一、结论：端点自报 20 个，实际可用 6 个 <a class="header-anchor" href="#一、结论-端点自报-20-个-实际可用-6-个" aria-label="Permalink to &quot;一、结论：端点自报 20 个，实际可用 6 个&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>延迟</th><th>状态</th></tr></thead><tbody><tr><td><code>qwen3.8-27b</code></td><td>0.2s</td><td>✔</td></tr><tr><td><code>glm-5.3-flash</code></td><td>0.5s</td><td>✔</td></tr><tr><td><strong><code>deepseek-v4.1-flash</code>（当前主模型）</strong></td><td>0.9s</td><td>✔</td></tr><tr><td><code>qwen3.8-flash</code></td><td>1.2s</td><td>✔</td></tr><tr><td><code>qwen3.7-max</code></td><td>1.3s</td><td>✔</td></tr><tr><td><code>deepseek-v4-pro</code></td><td>2.0s</td><td>✔</td></tr></tbody></table><p><strong>不可用 14 个</strong>（自报存在 ≠ 可用）：</p><ul><li><strong>503 Service Unavailable（端点侧未加载该模型）</strong>：<code>DeepSeek-V4-Flash</code>、<code>GW_DeepSeek-R1</code>、<code>Qwen3-Coder-Next</code>、<code>Qwen3.5-122B-A10B</code>、<code>Qwen3.6-27B</code>、<code>deepseek-v4-flash-0731</code>、<code>gemma-4-31B</code>、<code>qwen3.6-27b</code>、<code>qwen3.6-vl</code></li><li><strong>403 Forbidden（该 API key 无此模型权限）</strong>：<code>MiniMax/MiniMax-M2.7</code>、<code>ZHIPU/GLM-5.3</code>、<code>glm-5.1</code>、<code>glm-5.2</code>、<code>kimi-k2.6</code></li></ul><h2 id="二、两个-key-权限不同-重要" tabindex="-1">二、两个 key 权限不同（重要） <a class="header-anchor" href="#二、两个-key-权限不同-重要" aria-label="Permalink to &quot;二、两个 key 权限不同（重要）&quot;">​</a></h2><p><code>config.yaml</code> 里有<strong>两个 provider 指向同一端点</strong>：<code>123</code> 与 <code>123-copy</code>。</p><ul><li><code>glm-5.1</code>：用 <strong><code>123</code> 的 key → 可用（5.7s，回话正常）</strong>；用 <strong><code>123-copy</code> 的 key → 403 Forbidden</strong></li><li>两个 key 的 <code>/v1/models</code> 自报清单也不同（13 个 vs 15 个）</li></ul><p>→ <strong>「能用的模型」取决于用哪个 key</strong>。当前主模型走 <code>123-copy</code>。</p><h2 id="三、grok-46-provider-已失效" tabindex="-1">三、<code>grok-46</code> provider 已失效 <a class="header-anchor" href="#三、grok-46-provider-已失效" aria-label="Permalink to &quot;三、`grok-46` provider 已失效&quot;">​</a></h2><p><code>http://127.0.0.1:8787</code> → <strong>Connection refused</strong>（本地 grok 代理未运行）。该 provider 的 <code>grok-4.6</code> 完全不可达 → 建议清理该 provider 或修本地服务。</p><h2 id="四、判断口径-避免踩坑" tabindex="-1">四、判断口径（避免踩坑） <a class="header-anchor" href="#四、判断口径-避免踩坑" aria-label="Permalink to &quot;四、判断口径（避免踩坑）&quot;">​</a></h2><ol><li><strong><code>/v1/models</code> 自报 ≠ 可用</strong>：崩掉的 <code>deepseek-v4-flash-0731</code> 就挂在自报清单里。<strong>必须逐个发真实 chat completion 才算数。</strong></li><li><strong><code>max_tokens</code> 别设太小</strong>：给思考型模型设 32 时，<code>deepseek-v4-pro</code> / <code>glm-5.3-flash</code> 返回<strong>空 content</strong>（预算被思考吃掉）→ 易误判&quot;不可用&quot;。首轮用 <code>max_tokens: 1024</code> 测时两者回话均正常。</li><li><strong>区分 403 与 503</strong>：403 = key 权限（换 key 可解）；503 = 端点侧模型没起来（换 key 无用）。</li><li><strong>内网端点要禁本地代理</strong>：<code>http_proxy=127.0.0.1:8899</code> 会把内网请求一起劫持 → python 用 <code>ProxyHandler({})</code> 绕过。</li><li><strong>改 <code>config.yaml</code> 的姿势</strong>：<code>patch</code>/<code>write_file</code> 被安全策略拦；<code>hermes config set</code> <strong>不支持列表值</strong>（会把列表序列化成字符串）→ 用 python <strong>精确文本替换</strong>（先 <code>shutil.copy2</code> 备份 → 改完 <code>yaml.safe_load</code> 复验结构 + 统计残留次数）。</li></ol><p>关键词：内网 LLM 端点、new-api 网关、10.111.32.151 3001、模型盘点、可用性实测、503 模型未加载、403 权限不足、deepseek-v4.1-flash、qwen3.7-max、qwen3.8-flash、qwen3.8-27b、deepseek-v4-pro、glm-5.3-flash、deepseek-v4-flash-0731 删除、两个 key 权限差异、grok-46 失效、模型自报不等于可用、max_tokens 太小导致空回复、ProxyHandler 绕过本地代理</p><p>关联：<code>topics/ai-brain/index.md</code>、<code>topics/ai-brain/cron-idle-timeout-diagnosis.md</code></p>',16)])])}const m=o(r,[["render",n]]);export{h as __pageData,m as default};
